const r = await Promise.all([
  tools.exec_command({cmd:"bun --version; command -v doppler >/dev/null && doppler --version || echo 'doppler CLI not installed'; rg -n '\"(alchemy|wrangler|@cloudflare/vite-plugin|bun|effect)\"|packageManager' package.json apps/docs/package.json bun.lock | head -n 120","workdir":"/Users/cooper/.codex/worktrees/213f/taxkit","yield_time_ms":10000,"max_output_tokens":10000}),
  tools.exec_command({cmd:"jq -r '.results[] | [.title,.url,.publish_date] | @tsv' /tmp/taxkit-official-guidance.json","workdir":"/Users/cooper/.codex/worktrees/213f/taxkit","yield_time_ms":10000,"max_output_tokens":10000})
]); r.forEach((x,i)=>text(`---${i}---\n${x.output}`));

const searches = [
  {
    name:"/tmp/doppler-official.json",
    objective:"Current official Doppler documentation for projects, environments, configs, CLI setup/run, service tokens, service accounts and identities, GitHub Actions, secret visibility, audit and recovery. Need security requirements and version details.",
    queries:["site:docs.doppler.com/docs projects configs environments branching root config","site:docs.doppler.com/docs cli setup run service tokens service accounts identities oidc","site:docs.doppler.com/docs github actions masking secret visibility logs access"],
    domains:"docs.doppler.com,github.com"
  },
  {
    name:"/tmp/github-official.json",
    objective:"Current official GitHub Actions security guidance for secrets, environments, workflow permissions, masking, cache safety, action SHA pinning and OIDC. Need concrete CI design requirements.",
    queries:["site:docs.github.com/en/actions security hardening pin full length commit SHA secrets masking","site:docs.github.com/en/actions cache secrets sensitive files fork pull requests","site:docs.github.com/en/actions environments required reviewers deployment branches OIDC permissions"],
    domains:"docs.github.com,github.com"
  },
  {
    name:"/tmp/alchemy-cloudflare-official.json",
    objective:"Current official Alchemy and Cloudflare documentation for Alchemy configuration, stages, Cloudflare authentication inputs, state storage and encryption, GitHub Actions CI, Cloudflare API token least privilege and recovery.",
    queries:["site:alchemy.run docs config stages state encryption Cloudflare API token GitHub Actions","site:alchemy.run guides cloudflare authentication alchemy state store password","site:developers.cloudflare.com API tokens least privilege Workers account permissions token verify"],
    domains:"alchemy.run,developers.cloudflare.com,github.com"
  }
];
for (const s of searches) {
  const qs = s.queries.map(q=>`-q ${JSON.stringify(q)}`).join(" ");
  const cmd = `parallel-cli search ${JSON.stringify(s.objective)} ${qs} --include-domains ${s.domains} --json --max-results 20 --excerpt-max-chars-total 45000 -o ${s.name}`;
  const x = await tools.exec_command({cmd,workdir:"/Users/cooper/.codex/worktrees/213f/taxkit",yield_time_ms:30000,max_output_tokens:3000});
  text(`${s.name}: ${x.output.slice(0,2500)}`);
}
